@test "RCD-1 drift fixture (D-5.4): cache RUNNING, three COMPLETED markers with APPROVED trailers, ledger completed → COMPLETE; --write makes the cache say so" {
head/tests/unit/run-checkpoint-derive.bats:80:@test "RCD-1 drift fixture (D-5.4): cache RUNNING, three COMPLETED markers with APPROVED trailers, ledger completed → COMPLETE; --write makes the cache say so" {
head/tests/unit/run-checkpoint-derive.bats:101:@test "RCD-2 a stale marker whose trailers name sprint-1 of another cycle (or whose sprint: line names another sprint) is stale_marker, not counted" {
head/tests/unit/run-checkpoint-derive.bats:122:@test "RCD-3 legacy feedback (no LOA-VERDICT trailer) yields no verdict: the sprint stays incomplete and the file is named in derivation.legacy_feedback" {
head/tests/unit/run-checkpoint-derive.bats:135:@test "RCD-4 review and audit APPROVED without a marker is awaiting_marker (counted incomplete); a marker with the ledger row not completed is in_progress" {
head/tests/unit/run-checkpoint-derive.bats:154:@test "RCD-5 JACKED_OUT is terminal: a cache .state or .status JACKED_OUT, or .completion.merged_sha, stays JACKED_OUT with contradicting files reported as drift" {
head/tests/unit/run-checkpoint-derive.bats:175:@test "RCD-6 HALTED is sticky: a cache HALTED stays HALTED even when every sprint is complete; a breaker OPEN halts a RUNNING cache" {
head/tests/unit/run-checkpoint-derive.bats:189:@test "RCD-7 COMPLETE never moves back to RUNNING unless the ledger registers a new incomplete sprint" {
head/tests/unit/run-checkpoint-derive.bats:207:@test "RCD-8 an incomplete sprint is RUNNING while last_activity is within run_mode.stale_hours (default 12), else INTERRUPTED; the key widens the window" {
head/tests/unit/run-checkpoint-derive.bats:231:@test "RCD-9 breaker recompute: two -r1 feedback files and a zeroed breaker give cycle_count 2, same_issue 2, no_progress 1; counters are raised, never lowered" {
head/tests/unit/run-checkpoint-derive.bats:258:@test "RCD-10 three identical changes-required rounds meet the same-issue threshold: the derived breaker trips OPEN (history source derive) and the run derives HALTED" {
head/tests/unit/run-checkpoint-derive.bats:272:@test "RCD-11 schema tolerance: a file without derived_at, derivation or .status reads fine, gains the fields on --write and keeps its schema_version" {
head/tests/unit/run-checkpoint-derive.bats:291:@test "RCD-12 run_mode.file_authoritative: false makes --write report-only: the caches stay byte-identical and the report says why" {
